def solve(rows):
    kept = []
    state = 0
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 7 != 3 or i == len(rows) - 1:
            kept.append(row)
        state = 0 if weight == 0 else (3 * state + weight) % 7

    if not kept:
        return []

    final_state = state
    kept_length = len(kept)
    rotation = final_state % kept_length
    rotated_kept = kept[rotation:] + kept[:rotation]

    groups = {}
    for row in rotated_kept:
        if len(row) == 4 and isinstance(row[0], str) and isinstance(row[1], int) and isinstance(row[2], int) and isinstance(row[3], str):
            group = row[0]
            score = row[1]
            timestamp = row[2]
            name = row[3]

            if group not in groups:
                groups[group] = []
            groups[group].append((score, timestamp, name))

    result = []
    for group in sorted(groups.keys()):
        entries = groups[group]
